import SwaggerParser from "@apidevtools/swagger-parser";

// Usage: node extract-operation.mjs openapi.yaml POST /v1/orders/{orderId}/cancel
const [file, method, path] = process.argv.slice(2);
const api = await SwaggerParser.dereference(file, { dereference: { circular: "ignore" } });
const item = api.paths?.[path];
const op = item?.[method.toLowerCase()];
if (!op) {
  console.error(`No ${method} ${path} in ${file}`);
  process.exit(1);
}

// Drop vendor extensions (x-*) at every level; keep everything else.
const strip = (v) =>
  Array.isArray(v) ? v.map(strip)
  : v && typeof v === "object"
    ? Object.fromEntries(Object.entries(v).filter(([k]) => !k.startsWith("x-")).map(([k, x]) => [k, strip(x)]))
    : v;

const contract = {
  baseUrls: (api.servers ?? []).map((s) => s.url),
  auth: { required: op.security ?? api.security ?? [], schemes: api.components?.securitySchemes ?? {} },
  method: method.toUpperCase(),
  path,
  summary: op.summary,
  parameters: [...(item.parameters ?? []), ...(op.parameters ?? [])],
  requestBody: op.requestBody,
  responses: op.responses,
};

console.log(JSON.stringify(strip(contract), null, 2));

# Task
Add a typed `cancelOrder()` function to `src/api/orders.ts` and call it from the Cancel button in `src/features/orders/OrderActions.tsx`. Use only the contract below. If you need something it does not contain, stop and ask.

## Context
- API name: Shop Orders API
- Base URL: https://api.example.com (read it from `process.env.ORDERS_API_URL`)

## Endpoint contract
- Method: POST
- Path: `/v1/orders/{orderId}/cancel`
- Summary: Cancel an order that has not shipped
- Auth: bearerAuth (http bearer). Send `Authorization: Bearer <token>` using the token from `getSession()`.

**Parameters**

| Name | In | Type | Required | Description |
| --- | --- | --- | --- | --- |
| `orderId` | path | string (uuid) | yes | Order to cancel |
| `Idempotency-Key` | header | string | no | Makes retries safe |

**Request body** (`application/json`, required)

- `reason`: `"customer_request" | "fraud" | "out_of_stock"`, required
- `note`: string, max 500 characters, optional

**Responses**

- `200`: the updated order (`Order` below)
- `401`: missing or expired token, no body
- `404`: order not found, `ProblemDetails` body
- `409`: order already shipped or cancelled, `ProblemDetails` body
- `422`: body failed validation, `ProblemDetails` body with `errors`

## Types
```ts
export type CancelReason = "customer_request" | "fraud" | "out_of_stock";

export interface CancelOrderBody {
  reason: CancelReason;
  /** Max 500 characters. */
  note?: string;
}

export interface Order {
  id: string;
  status: "pending" | "paid" | "shipped" | "cancelled";
  total_cents: number;
  currency: string;
  /** ISO 8601 date-time. Null until the order is cancelled. */
  cancelled_at: string | null;
}

export interface ProblemDetails {
  type: string;
  title: string;
  status: number;
  detail?: string;
  errors?: { field: string; message: string }[];
}
```

## Requirements
- Use the exact path, header and field names above. JSON fields are snake_case.
- Call no other endpoint and send no field that is not listed.
- Disable the Cancel button while the request is in flight.
- On 409, show `detail` and refetch the order. On 401, redirect to sign-in.
- Throw an `ApiError` with `status` and the parsed body for every non-2xx response.

## Acceptance criteria
- [ ] Sends POST {base}/v1/orders/{orderId}/cancel with `orderId` URL-encoded
- [ ] Body has `reason`, and `note` only when the user typed one
- [ ] Success is typed as `Order`, with `cancelled_at` as `string | null`
- [ ] 401, 404, 409 and 422 each have a handled branch
- [ ] No field outside the contract is read or sent
